<?php require '_top.php';if(isset($_GET['delete'])){db()->prepare('DELETE FROM contatos WHERE id=?')->execute([(int)$_GET['delete']]);header('Location: contatos.php');exit;}if(isset($_GET['read'])){db()->prepare("UPDATE contatos SET status='lida' WHERE id=?")->execute([(int)$_GET['read']]);header('Location: contatos.php');exit;}?><h1>Mensagens recebidas</h1><div class="cards grid"><?php foreach(rows('contatos','criado_em') as $x):?><article><b><?=e($x['status'])?></b><h3><?=e($x['assunto'])?></h3><p><?=e($x['nome'])?> · <?=e($x['email'])?></p><p><?=e($x['mensagem'])?></p><a href="?read=<?=$x['id']?>">Marcar como lida</a> · <a href="?delete=<?=$x['id']?>" onclick="return confirm('Excluir mensagem?')">Excluir</a></article><?php endforeach?></div><?php require '_bottom.php'; ?>
